import React, { useState } from 'react';
import { Grommet, Box, DataTable, Button } from 'grommet';

const sampleData = [
  {
    id: 'f6ca62b1-d3bf-48f6-xxxx-xxxxxxxxxxxx',
    name: 'check github',
    parent: null,          // renders as “--”
    order: 0,
    children: 2,
  },
  {
    id: '4efe5f56-2214-4872-xxxx-xxxxxxxxxxxx',
    name: 'Poll Remote Site',
    parent: 'f6ca62b1-d3bf-48f6-xxxx-xxxxxxxxxxxx',
    order: 0,
    children: 0,
  },
  {
    id: 'bdb9d701-31c6-4831-xxxx-xxxxxxxxxxxx',
    name: 'Compare with previous snapshot',
    parent: 'f6ca62b1-d3bf-48f6-xxxx-xxxxxxxxxxxx',
    order: 1,
    children: 0,
  },
  {
    id: '31ba8ef8-6c07-40bc-xxxx-xxxxxxxxxxxx',
    name: 'Load Snapshots',
    parent: undefined,     // also renders as “--”
    order: 0,
    children: 0,
  },
];

export const App = () => {
  // initialize sort on the "parent" column
  const [sort, setSort] = useState({ property: 'parent', direction: 'asc' });

  const columns = [
    { property: 'id', header: 'ID' },
    { property: 'name', header: 'Name' },
    {
      property: 'parent',
      header: 'Parent',
      render: datum => datum.parent || '--',
    },
    { property: 'order', header: 'Order' },
    { property: 'children', header: 'Children' },
    {
      header: 'Actions',
      render: () => <Button label="Edit" />, // placeholder
    },
  ];

  return (
    <Grommet>
      <Box pad="medium">
        <DataTable
          columns={columns}
          data={sampleData}
          sort={sort}
          onSort={nextSort => setSort(nextSort)}
        />
      </Box>
    </Grommet>
  );
};
